        "content": "{\n    \"name\": \"Pega_Extensions_ProfileCard\",\n    \"label\": \"Profile Card\",\n    \"description\": \"Displays a polished profile card with a mapped case image, identity details, status, and interactive tilt.\",\n    \"organization\": \"Pega\",\n    \"version\": \"5.0.4\",\n    \"library\": \"Extensions\",\n    \"allowedApplications\": [],\n    \"componentKey\": \"Pega_Extensions_ProfileCard\",\n    \"type\": \"Widget\",\n    \"subtype\": [\n        \"PAGE\",\n        \"CASE\"\n    ],\n    \"properties\": [\n        {\n            \"name\": \"name\",\n            \"label\": \"Name\",\n            \"format\": \"PROPERTY\",\n            \"defaultValue\": \"@P .CustomerName\"\n        },\n        {\n            \"name\": \"title\",\n            \"label\": \"Title\",\n            \"format\": \"PROPERTY\",\n            \"defaultValue\": \"@P .CustomerType\"\n        },\n        {\n            \"name\": \"handle\",\n            \"label\": \"Handle\",\n            \"format\": \"PROPERTY\",\n            \"defaultValue\": \"@P .CustomerID\"\n        },\n        {\n            \"name\": \"status\",\n            \"label\": \"Status\",\n            \"format\": \"PROPERTY\",\n            \"defaultValue\": \"@P .CaseStatus\"\n        },\n        {\n            \"name\": \"imageProperty\",\n            \"label\": \"Image property\",\n            \"format\": \"PROPERTY\",\n            \"defaultValue\": \"@P .ProfileImage\"\n        },\n        {\n            \"name\": \"imageAttachmentProperty\",\n            \"label\": \"Attachment property\",\n            \"format\": \"PROPERTY\",\n            \"defaultValue\": \"@P .ProfileAttachment\"\n        },\n        {\n            \"name\": \"imageAttachmentCategory\",\n            \"label\": \"Image attachment category\",\n            \"format\": \"TEXT\",\n            \"defaultValue\": \"Image\"\n        },\n        {\n            \"name\": \"imageAttachmentName\",\n            \"label\": \"Image attachment filename\",\n            \"format\": \"TEXT\",\n            \"defaultValue\": \"\"\n        },\n        {\n            \"name\": \"showUserInfo\",\n            \"label\": \"Show profile metadata\",\n            \"format\": \"BOOLEAN\",\n            \"defaultValue\": true\n        },\n        {\n            \"name\": \"enableTilt\",\n            \"label\": \"Enable hover tilt\",\n            \"format\": \"BOOLEAN\",\n            \"defaultValue\": true\n        },\n        {\n            \"label\": \"Conditions\",\n            \"format\": \"GROUP\",\n            \"properties\": [\n                {\n                    \"name\": \"visibility\",\n                    \"label\": \"Visibility\",\n                    \"format\": \"VISIBILITY\"\n                }\n            ]\n        },\n        {\n            \"format\": \"LABEL\",\n            \"label\": \"About\",\n            \"name\": \"PegaAboutLabel\",\n            \"variant\": \"h3\"\n        },\n        {\n            \"format\": \"LABEL\",\n            \"label\": \"Pega_Extensions 5.0.4, Tue Sep 22 2026, 26.1.1-105720\",\n            \"name\": \"PegaAboutData\",\n            \"variant\": \"primary\"\n        }\n    ],\n    \"defaultConfig\": {\n        \"name\": \"Javi A. Torres\",\n        \"title\": \"Software Engineer\",\n        \"handle\": \"javicodes\",\n        \"status\": \"Online\",\n        \"imageProperty\": \"ProfileImage\",\n        \"imageAttachmentProperty\": \"ProfileAttachment\",\n        \"showUserInfo\": true,\n        \"enableTilt\": true\n    },\n    \"buildDate\": \"2026-09-22T07:13:31.696Z\",\n    \"infinityVersion\": \"26.1.1-105720\",\n    \"packageCosmosVersion\": \"9.23.4\"\n}"
